using System.Drawing;using System.Windows.Forms;
namespace LSE.AutoCADElectrical.ProjectTools;
public sealed class ProjectSettingsForm:Form{readonly AppSettings s=SettingsService.Load();readonly Dictionary<string,TextBox> boxes=new();readonly Dictionary<string,CheckBox> checks=new();
 public ProjectSettingsForm(){Text="LSE Project Tools Settings (Lake Shore Electric)";StartPosition=FormStartPosition.CenterParent;Size=new Size(1040,760);MinimumSize=new Size(800,600);var p=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=3,Padding=new Padding(12),AutoScroll=true};p.ColumnStyles.Add(new(SizeType.Absolute,250));p.ColumnStyles.Add(new(SizeType.Percent,100));p.ColumnStyles.Add(new(SizeType.Absolute,100));int r=0;
  Add(p,"Jobs root (Custom Sales Order)",nameof(s.ProjectsRootFolder),s.ProjectsRootFolder,r++,"folder");Add(p,"LSE template project (.wdp)",nameof(s.BaseProjectPath),s.BaseProjectPath,r++,"AutoCAD Electrical project (*.wdp)|*.wdp");Add(p,"Drawing template (DRAWING-#.dwg)",nameof(s.DrawingTemplatePath),s.DrawingTemplatePath,r++,"Drawing template (*.dwg;*.dwt)|*.dwg;*.dwt");Add(p,"Project templates JSON",nameof(s.TemplatesConfigPath),s.TemplatesConfigPath,r++,"JSON (*.json)|*.json");Add(p,"Symbol library folder (wd_m.dwg)",nameof(s.SymbolLibraryFolder),s.SymbolLibraryFolder,r++,"folder");
  Add(p,"Default product line",nameof(s.DefaultProductLine),s.DefaultProductLine,r++);Add(p,"Default drawing set",nameof(s.DefaultProjectType),s.DefaultProjectType,r++);Add(p,"Date format",nameof(s.DateFormat),s.DateFormat,r++);Add(p,"Drawn by (default)",nameof(s.DrawnBy),s.DrawnBy,r++);Add(p,"Activate project LISP ({WDP})",nameof(s.ActivateProjectLisp),s.ActivateProjectLisp,r++);
  Check(p,"Fill title block attributes (ECAD_LSE_CUSTOM_TB_2.0)",nameof(s.FillTitleBlocks),s.FillTitleBlocks,r++);Check(p,"Set WD_M sheet / IEC values",nameof(s.SetWdmValues),s.SetWdmValues,r++);Check(p,"Write <job>.wdt title block mapping",nameof(s.WriteWdtFile),s.WriteWdtFile,r++);Check(p,"Write <job>_wdtitle.wdl description labels",nameof(s.WriteWdlFile),s.WriteWdlFile,r++);Check(p,"Copy the template's own .wdt / .wdl instead of generating them",nameof(s.CopyTemplateSidecars),s.CopyTemplateSidecars,r++);Check(p,"Write <job>.aepx project configuration",nameof(s.WriteAepxFile),s.WriteAepxFile,r++);Check(p,"Activate project after creation",nameof(s.ActivateProject),s.ActivateProject,r++);Check(p,"Open first drawing after creation",nameof(s.OpenFirstDrawing),s.OpenFirstDrawing,r++);
  var save=new Button{Text="Save",Dock=DockStyle.Fill};save.Click+=(_,_)=>{try{s.ProjectsRootFolder=boxes[nameof(s.ProjectsRootFolder)].Text.Trim();s.BaseProjectPath=boxes[nameof(s.BaseProjectPath)].Text.Trim();s.DrawingTemplatePath=boxes[nameof(s.DrawingTemplatePath)].Text.Trim();s.TemplatesConfigPath=boxes[nameof(s.TemplatesConfigPath)].Text.Trim();s.SymbolLibraryFolder=boxes[nameof(s.SymbolLibraryFolder)].Text.Trim();s.DefaultProductLine=boxes[nameof(s.DefaultProductLine)].Text.Trim();s.DefaultProjectType=boxes[nameof(s.DefaultProjectType)].Text.Trim();s.DateFormat=boxes[nameof(s.DateFormat)].Text.Trim();s.DrawnBy=boxes[nameof(s.DrawnBy)].Text.Trim();s.ActivateProjectLisp=boxes[nameof(s.ActivateProjectLisp)].Text.Trim();
   s.FillTitleBlocks=checks[nameof(s.FillTitleBlocks)].Checked;s.SetWdmValues=checks[nameof(s.SetWdmValues)].Checked;s.WriteWdtFile=checks[nameof(s.WriteWdtFile)].Checked;s.WriteWdlFile=checks[nameof(s.WriteWdlFile)].Checked;s.CopyTemplateSidecars=checks[nameof(s.CopyTemplateSidecars)].Checked;s.WriteAepxFile=checks[nameof(s.WriteAepxFile)].Checked;s.ActivateProject=checks[nameof(s.ActivateProject)].Checked;s.OpenFirstDrawing=checks[nameof(s.OpenFirstDrawing)].Checked;_=DateTime.Now.ToString(s.DateFormat);SettingsService.Save(s);DialogResult=DialogResult.OK;Close();}catch(Exception ex){MessageBox.Show(ex.Message,"LSE Project Tools Settings");}};
  var diag=new Button{Text="Diagnostics",Dock=DockStyle.Fill};diag.Click+=(_,_)=>MessageBox.Show(DiagnosticsService.BuildReport(),"LSE Project Tools Diagnostics");p.RowStyles.Add(new(SizeType.Absolute,48));p.Controls.Add(diag,0,r);p.Controls.Add(save,2,r);Controls.Add(p);}
 void Add(TableLayoutPanel p,string label,string key,string value,int row,string? browse=null){p.RowStyles.Add(new(SizeType.Absolute,48));p.Controls.Add(new Label{Text=label,AutoSize=true,Anchor=AnchorStyles.Left},0,row);var t=new TextBox{Text=value,Dock=DockStyle.Fill};boxes[key]=t;p.Controls.Add(t,1,row);if(browse is null)return;var b=new Button{Text="Browse",Dock=DockStyle.Fill};b.Click+=(_,_)=>{if(browse=="folder"){using var f=new FolderBrowserDialog{SelectedPath=Directory.Exists(t.Text)?t.Text:""};if(f.ShowDialog()==DialogResult.OK)t.Text=f.SelectedPath;}else{using var f=new OpenFileDialog{Filter=browse,FileName=t.Text};if(f.ShowDialog()==DialogResult.OK)t.Text=f.FileName;}};p.Controls.Add(b,2,row);}
 void Check(TableLayoutPanel p,string label,string key,bool value,int row){p.RowStyles.Add(new(SizeType.Absolute,34));var c=new CheckBox{Text=label,Checked=value,AutoSize=true,Anchor=AnchorStyles.Left};checks[key]=c;p.Controls.Add(c,1,row);}
}
